import {request} from './api.js';

const $ = (s,root=document) => root.querySelector(s);
const $$ = (s,root=document) => [...root.querySelectorAll(s)];
const escape = value => String(value ?? '').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const e = escape;
const icons = {
 moon:'<path d="M20.5 13.2A8.5 8.5 0 0 1 10.8 3.5a8.5 8.5 0 1 0 9.7 9.7Z"/>',
 sun:'<circle cx="12" cy="12" r="4"/><path d="M12 2v2M12 20v2M2 12h2M20 12h2M4.9 4.9l1.4 1.4M17.7 17.7l1.4 1.4M4.9 19.1l1.4-1.4M17.7 6.3l1.4-1.4"/>',
 search:'<circle cx="10.5" cy="10.5" r="6.5"/><path d="m16 16 4.5 4.5"/>',
 heart:'<path d="M20.5 5.6c-2.1-2.1-5.5-1.6-8.5 1.4-3-3-6.4-3.5-8.5-1.4-2.2 2.2-1.8 5.9 1 8.7L12 21l7.5-6.7c2.8-2.8 3.2-6.5 1-8.7Z"/>',
 pin:'<path d="M19 10c0 5-7 11-7 11S5 15 5 10a7 7 0 0 1 14 0Z"/><circle cx="12" cy="10" r="2.5"/>',
 compare:'<path d="M5 4v16M12 4v16M19 4v16M2 9h6M9 15h6M16 7h6"/>',
 user:'<circle cx="12" cy="8" r="4"/><path d="M4 21v-2a8 8 0 0 1 16 0v2"/>',
 plus:'<path d="M12 5v14M5 12h14"/>',
 bell:'<path d="M18 8a6 6 0 0 0-12 0c0 7-3 7-3 9h18c0-2-3-2-3-9ZM10 21h4"/>',
 menu:'<path d="M4 6h16M4 12h16M4 18h16"/>',
 chevron:'<path d="m9 5 7 7-7 7"/>',
 down:'<path d="m6 9 6 6 6-6"/>',
 back:'<path d="m14 5-7 7 7 7M7 12h14"/>',
 close:'<path d="m6 6 12 12M6 18 18 6"/>',
 check:'<path d="m5 12 4 4L19 6"/>',
 shield:'<path d="m12 3 8 3v6c0 5-8 9-8 9s-8-4-8-9V6Z"/><path d="m8 12 3 3 5-6"/>',
 grid:'<rect x="4" y="4" width="6" height="6" rx="1"/><rect x="14" y="4" width="6" height="6" rx="1"/><rect x="4" y="14" width="6" height="6" rx="1"/><rect x="14" y="14" width="6" height="6" rx="1"/>',
 list:'<path d="M9 5h12M9 12h12M9 19h12M3 5h1M3 12h1M3 19h1"/>',
 filter:'<path d="M3 6h18M3 12h18M3 18h18"/><circle cx="8" cy="6" r="2" fill="currentColor"/><circle cx="16" cy="12" r="2" fill="currentColor"/><circle cx="9" cy="18" r="2" fill="currentColor"/>',
 ads:'<rect x="4" y="3" width="16" height="18" rx="2"/><path d="M8 7h8M8 11h8M8 15h5"/>',
 chat:'<path d="M21 11a8 8 0 0 1-8 8H8l-5 3V5a2 2 0 0 1 2-2h14a2 2 0 0 1 2 2Z"/><path d="M7 8h10M7 12h6"/>',
 settings:'<path d="m10 3-1 3-3 1-2 3 1 3-1 3 3 2 3-1 2 3 3-1 1-3 3-1 1-3-2-2 1-3-3-2-3 1Z"/><circle cx="12" cy="12" r="3"/>',
 help:'<circle cx="12" cy="12" r="9"/><path d="M9 8a3 3 0 0 1 6 1c0 2-3 2-3 5M12 17h.01"/>',
 edit:'<path d="m15 4 5 5M4 20l1-5L16 4a2 2 0 0 1 3 0l1 1a2 2 0 0 1 0 3L9 19Z"/>',
 more:'<circle cx="12" cy="5" r="1"/><circle cx="12" cy="12" r="1"/><circle cx="12" cy="19" r="1"/>',
 photo:'<rect x="3" y="4" width="18" height="16" rx="2"/><circle cx="8" cy="9" r="2"/><path d="m3 18 5-5 4 3 4-6 5 6"/>',
 phone:'<path d="m6 3 4 4-3 3c1 3 4 6 7 7l3-3 4 4c-1 3-3 4-6 3C9 19 5 15 3 9 2 6 3 4 6 3Z"/>',
 send:'<path d="m3 3 18 9-18 9 3-9-3-9ZM6 12h15"/>',
 clip:'<path d="m9 14 7-7a3 3 0 0 1 4 4L10 21a5 5 0 0 1-7-7L14 3"/>',
 archive:'<rect x="3" y="3" width="18" height="5" rx="1"/><path d="M5 8v13h14V8M9 12h6"/>',
 trash:'<path d="M3 6h18M8 6V3h8v3M5 6l1 15h12l1-15M10 10v7M14 10v7"/>',
 refresh:'<path d="M20 5v6h-6M4 19v-6h6M20 11a8 8 0 0 0-14-5M4 13a8 8 0 0 0 14 5"/>',
 logout:'<path d="M9 4H4v16h5M14 7l5 5-5 5M8 12h13"/>',
 download:'<path d="M12 3v12m-5-5 5 5 5-5M4 16v5h16v-5"/>',
 clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>',
 globe:'<circle cx="12" cy="12" r="9"/><path d="M3 12h18M12 3a18 18 0 0 1 0 18 18 18 0 0 1 0-18"/>',
 eye:'<path d="M2 12s4-7 10-7 10 7 10 7-4 7-10 7S2 12 2 12Z"/><circle cx="12" cy="12" r="3"/>',
 building:'<path d="M4 21V3h12v18M16 9h4v12M8 7h4M8 11h4M8 15h4M9 21v-3h2v3"/>',
 laptop:'<rect x="5" y="3" width="14" height="12" rx="1"/><path d="m5 15-3 5h20l-3-5"/>'
};
const icon = name => `<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${icons[name]||icons.ads}</svg>`;
const fmt = v => v === null || v === undefined || v === '' ? '—' : Number(v).toLocaleString('ru-RU');
const money = v => v ? `${fmt(v)} ₽` : 'Цена не указана';
const date = v => v ? new Date(v).toLocaleDateString('ru-RU',{day:'numeric',month:'long'}) : '';
const time = v => new Date(v).toLocaleTimeString('ru-RU',{hour:'2-digit',minute:'2-digit'});
const assets = {volvo:'Volvo FH 500',kamaz:'КАМАЗ 54901',cat:'CAT 320',jcb:'JCB 3CX',shacman:'Shacman X3000',man:'MAN TGX',trailer:'Полуприцеп',car:'Toyota Camry',moto:'Yamaha MT-07',boat:'Моторная лодка'};
let state, summary, meta, renderToken=0, toastTimer, modalReturnFocus;
let ui={view:'grid',diff:false,chatFilter:'',editor:null,editorKey:null,step:1,preview:false,chatAttachment:null,profileAvatar:null,supportAttachment:null,galleryIndex:0,galleryAd:null};
const user = () => state?.users[state.user_id];
const ad = id => state.ads.find(a=>a.id===String(id));
const seller = id => state.users[id] || state.sellers.find(s=>s.id===id) || {name:'Пользователь',city:'',kind:'private'};
const own = a => a.owner === state.user_id;
const favs = () => state.favorites[state.user_id] || [];
const status = a => `<span class="status ${e(a.status)}">${a.status==='active'?icon('check'):''}${e(meta.statuses[a.status])}</span>`;
const photo = (a,cls='',index=0) => a.photos?.length ? `<img class="${cls}" src="${e(a.photos[index]||a.photos[0])}" alt="${e(a.title)}" loading="lazy">` : `<div class="photo-placeholder ${cls}">${icon('photo')}</div>`;
const avatar = (person,cls='') => `<span class="avatar ${cls}">${person.avatar?`<img src="${e(person.avatar)}" alt="">`:e(person.initials||person.name?.slice(0,1)||'А')}</span>`;
const mileage = a => meterFor(a.category)==='hours' ? `${fmt(a.hours)} м/ч` : meterFor(a.category)==='mileage' ? `${fmt(a.mileage)} км` : a.length ? `${fmt(a.length)} м` : '';
const specLine = a => [a.year||'Год не указан',mileage(a),a.section==='water'?(a.motor_power?`${fmt(a.motor_power)} л. с.`:''):a.wheels||a.body||a.vehicle_class||''].filter(Boolean).map(e).join(' · ');
const field = (name,label,value='',extra='') => `<div class="field"><label for="f-${e(name)}">${label}</label><input id="f-${e(name)}" name="${e(name)}" value="${e(value)}" ${extra}></div>`;
const options = (items,value) => Object.entries(items).map(([k,v])=>`<option value="${e(k)}" ${String(k)===String(value)?'selected':''}>${e(v)}</option>`).join('');
const selectField = (name,label,items,value='',extra='') => `<div class="field"><label for="f-${e(name)}">${label}</label><select id="f-${e(name)}" name="${e(name)}" ${extra}>${options(items,value)}</select></div>`;
const cities = (blank='Любой город') => Object.fromEntries([['',blank],...Object.keys(meta.cities).map(c=>[c,c])]);
const button = (text,action,ico='',cls='',data='') => `<button type="button" class="btn ${cls}" data-action="${action}" ${data}>${ico?icon(ico):''}${text}</button>`;
const ib = (action,ico,label,data='',cls='') => `<button type="button" class="icon-btn ${cls}" data-action="${action}" aria-label="${e(label)}" title="${e(label)}" ${data}>${icon(ico)}</button>`;
const linkButton=(text,href,ico='',cls='')=>`<a class="btn ${cls}" href="#${href}">${ico?icon(ico):''}${text}</a>`;
const switcher = (label,checked,action,data='') => `<label class="switch"><input type="checkbox" ${checked?'checked':''} data-change="${action}" ${data}><span class="switch-track"></span>${label}</label>`;
function toast(message,error=false){ clearTimeout(toastTimer); $('#toast').innerHTML=`<div class="toast ${error?'error':''}">${e(message)}</div>`;toastTimer=setTimeout(()=>$('#toast').innerHTML='',4500); }
async function call(action,payload={}){
 const response=await request(action,payload);
 if(!response.ok){const error=new Error(response.error.message);error.fields=response.error.fields||{};throw error;}
 state=response.state;summary=response.summary;return response.result;
}
function route(){const raw=(location.hash||'#/catalog').slice(1);const [path,query='']=raw.split('?');return {path,parts:path.split('/').filter(Boolean),params:Object.fromEntries(new URLSearchParams(query))};}
function href(path,params={}){const q=new URLSearchParams(Object.entries(params).filter(([,v])=>v!==''&&v!=null));return path+(q.size?'?'+q:'');}
function go(path,params={}){closeModal();const hash='#'+href(path,params);if(location.hash===hash)render();else location.hash=hash;}
function fail(err){if(err.fields?.auth){openLogin();return;}toast(err.message||'Не удалось выполнить действие',true);}
function empty(title,text,action='',ico='search'){return `<div class="empty"><div class="empty-icon">${icon(ico)}</div><h2>${title}</h2><p>${text}</p>${action}</div>`;}
function showModal(title,body,cls=''){
 modalReturnFocus=document.activeElement;
 $('#overlay').innerHTML=`<div class="modal-backdrop" data-dismiss="true"><section class="modal ${cls}" role="dialog" aria-modal="true" aria-labelledby="modal-title"><div class="modal-head"><h2 id="modal-title">${title}</h2>${ib('close','close','Закрыть')}</div><div class="modal-body">${body}</div></section></div>`;
 document.body.style.overflow='hidden'; setTimeout(()=>$('.modal input:not([type=hidden]),.modal button')?.focus(),30);
}
function closeModal(){if(!$('#overlay').innerHTML)return;$('#overlay').innerHTML='';document.body.style.overflow='';if(modalReturnFocus?.isConnected)modalReturnFocus.focus();}
function footer(){return `<footer class="footnote"><span>ТЯГА · Транспорт и спецтехника</span><span>Демонстрационные объявления</span></footer>`;}
function themeToggle(){const dark=document.documentElement.dataset.theme==='dark';return `<button type="button" class="icon-btn theme-toggle" data-theme-toggle role="switch" aria-checked="${dark}" aria-label="Тёмная тема" title="${dark?'Включить светлую тему':'Включить тёмную тему'}"><span class="theme-icon-moon">${icon('moon')}</span><span class="theme-icon-sun">${icon('sun')}</span></button>`;}
function shell(content,r){
 const p=r.parts[0]; const isAccount=p==='account';
 const nav=[['/catalog','grid','Каталог'],['/account/favorites','heart','Избранное'],['/create','plus','Разместить'],['/account/messages','chat','Сообщения'],[isModerator()?'/moderator':'/account/ads','user',isModerator()?'Модерация':'Кабинет']];
 return `<div class="demo-bar"><span>Демо · <b>${e(user()?.name||'Гость')}</b><span class="demo-storage"> · ${window.TYAGA_SERVER?'данные в SQLite':'изменения сохраняются в этом браузере'}</span></span><div class="demo-role-actions">${isModerator()?'<a href="#/moderator">Кабинет модератора</a>':''}<button data-action="demo">Сценарии демо</button></div></div>
 <header class="header"><div class="header-inner"><a href="#/catalog" class="logo" aria-label="ТЯГА, главная">ТЯГА</a><nav class="header-nav" aria-label="Основная навигация"><a class="${p==='catalog'?'active':''}" href="#/catalog">Каталог</a><a class="${p==='dealers'||p==='dealer'?'active':''}" href="#/dealers">Дилеры</a>${isModerator()?`<a class="${p==='moderator'?'active':''}" href="#/moderator">Модерация</a>`:''}</nav><div class="header-actions"><button class="btn plain location-header" data-action="location">${icon('pin')}${e(r.params.city||'Вся Россия')}</button><button class="mobile-location mobile-only" data-action="location">${icon('pin')}<span class="header-location-name">${e(r.params.city||'Вся Россия')}</span>${icon('down')}</button>${themeToggle()}<a href="#/account/favorites">${icon('heart')}<span class="action-label">Избранное</span></a><a href="#/compare">${icon('compare')}<span class="action-label">Сравнение</span>${state.compare.length?`<span class="count">${state.compare.length}</span>`:''}</a>${user()?`<button class="icon-btn notification" data-action="notices" aria-label="Уведомления">${icon('bell')}${summary.notices?`<span class="badge">${summary.notices}</span>`:''}</button><a href="#/account/profile">${avatar(user())}<span class="action-label">${e(user().name)}</span></a>`:button('Войти','login','user','plain')}<a class="btn primary" href="#/create">${icon('plus')}Разместить объявление</a></div></div></header>
 <main class="container ${p==='ad'?'detail-page':''}" id="main-content">${content}${footer()}</main><nav class="bottom-nav" aria-label="Мобильная навигация">${nav.map(([path,i,label])=>`<a href="#${path}" class="${(path==='/catalog'&&p==='catalog')||(path==='/create'&&['create','edit'].includes(p))||(path==='/account/ads'&&isAccount&&!['favorites','messages'].includes(r.parts[1]))||r.path===path?'active':''}">${i==='plus'?`<span class="add-circle">${icon(i)}</span>`:icon(i)}${label}${i==='chat'&&summary.unread?`<span class="badge">${summary.unread}</span>`:''}</a>`).join('')}</nav>`;
}
function accountNav(active,mobile=false){
 const entries=[['ads','ads','Мои объявления',''],['messages','chat','Сообщения',summary.unread],['favorites','heart','Избранное',summary.favorites],['searches','search','Сохранённые поиски',(state.searches[state.user_id]||[]).length],['profile','settings','Профиль и настройки',''],['help','help','Помощь','']];
 return `<nav class="${mobile?'account-mobile-menu mobile-only':'account-nav'}" aria-label="Личный кабинет">${entries.map(([key,i,label,n])=>`<a href="#/account/${key}" class="${key===active?'active':''}">${icon(i)}<span>${label}</span>${n?`<span class="${key==='messages'?'badge':'count'}">${n}</span>`:''}</a>`).join('')}</nav>`;
}
function account(content,active){return `<div class="account-layout"><aside class="account-sidebar panel"><div class="account-user">${avatar(user())}<div><strong>${e(user().name)}</strong><p>${user().kind==='company'?'Компания':'Частное лицо'}</p></div></div>${accountNav(active)}</aside><section class="account-main">${accountNav(active,true)}${content}</section></div>`;}
function card(a){const f=favs().includes(a.id),c=state.compare.includes(a.id);return `<article class="vehicle-card"><a class="vehicle-photo" href="#/ad/${e(a.id)}">${photo(a)}${a.photos.length?`<span class="photo-count">${icon('photo')}${a.photos.length}</span>`:''}</a>${ib('favorite','heart',f?'Убрать из избранного':'В избранное',`data-id="${e(a.id)}" aria-pressed="${f}"`,`favorite-button ${f?'on':''}`)}<div class="vehicle-info"><a href="#/ad/${e(a.id)}"><div class="price">${money(a.price)}</div><h3>${e(a.title)}</h3></a><p class="spec-line">${specLine(a)}</p><p class="location">${icon('pin')}${e(a.city)}</p><div class="card-bottom">${a.status==='active'?`<span class="status active">${icon(own(a)?'user':'shield')}${own(a)?'Ваше объявление':seller(a.owner).kind==='dealer'?'Дилер':'Частный продавец'}</span>`:status(a)}<button class="compare-card-btn ${c?'on':''}" data-action="compare" data-id="${e(a.id)}" aria-label="${c?'Убрать из сравнения':'Сравнить'}" aria-pressed="${c}" title="${c?'Убрать из сравнения':'Сравнить'}">${icon('compare')}</button></div></div></article>`;}
function plural(n,one,few,many){const x=n%100,y=n%10;return x>10&&x<20?many:y===1?one:y>=2&&y<=4?few:many;}
function detail(a){
 if(!a||a.status==='deleted'||(!own(a)&&!['active','sold','archived'].includes(a.status)))return empty('Объявление недоступно','Откройте каталог, чтобы выбрать другую технику.',linkButton('В каталог','/catalog','search','primary'));
 const s=seller(a.owner),active=a.status==='active';
 const contacts=own(a)?`${linkButton('Редактировать',`/edit/${a.id}`,'edit','primary')}${linkButton('Мои объявления','/account/ads','ads')}`:active?`${button('Написать','start-chat','chat','primary',`data-id="${a.id}"`)}${button('Показать телефон','phone','phone','',`data-id="${a.id}"`)}`:linkButton('Найти похожее','/catalog?category='+a.category,'search','primary');
 return `<div class="breadcrumb"><a href="${e(ui.catalogReturn?.hash||'#/catalog')}">К результатам поиска</a>${icon('chevron')}<a href="#/catalog?category=${a.category}">${e(meta.categories[a.category])}</a>${icon('chevron')}<span>${e(a.title)}</span></div><div class="page-head"><div><h1>${e(a.title)}</h1><p class="spec-line">${specLine(a)} · ${e(a.city)}</p></div><div class="row gap-sm">${ib('favorite','heart','Избранное',`data-id="${a.id}"`,favs().includes(a.id)?'selected':'')}${ib('compare','compare','Сравнить',`data-id="${a.id}"`,state.compare.includes(a.id)?'selected':'')}</div></div>${!active?`<div class="notice-box ${a.status==='rejected'?'red':'amber'} mb">${status(a)} <span>${a.status==='sold'?'Техника продана. Посмотрите похожие объявления.':a.status==='pending'?'Это объявление пока видно только вам.':a.status==='rejected'?e(a.rejection):'Это объявление не показывается в каталоге.'}</span></div>`:''}<div class="detail-grid"><div><div class="gallery"><button data-action="gallery" data-id="${a.id}" aria-label="Открыть фотографии">${photo(a)}</button><span class="gallery-tag">${icon('photo')} ${a.photos.length} фото · увеличить</span></div>${a.photos.length>1?`<div class="thumbs">${a.photos.map((src,i)=>`<button data-action="gallery" data-id="${a.id}" data-index="${i}"><img src="${e(src)}" alt="Фото ${i+1}"></button>`).join('')}</div>`:''}<section class="panel mt"><h2>Характеристики</h2><div class="specs">${specs(a).map(([k,v])=>`<div class="spec-item"><span>${k}</span><strong>${e(v)}</strong></div>`).join('')}</div></section><section class="panel mt"><h2 class="mb">Описание</h2><p class="description">${e(a.description)||'Описание ещё не добавлено'}</p></section><section class="panel mt mobile-only mobile-seller"><div class="row">${avatar(s)}<div><h3>${e(s.name)}</h3><p class="muted small">${s.kind==='dealer'?'Дилер':'Частный продавец'} · ${e(s.city)}</p></div></div>${s.kind==='dealer'?`<a class="text-link small" href="#/dealer/${e(s.id)}">Все объявления продавца →</a>`:''}</section></div><aside class="seller-box panel"><div class="price">${money(a.price)}</div><p class="vat-label">${a.vat==='yes'?'Включая НДС':'Без НДС'} · ${e(a.city)}</p><div class="stack contact-stack">${contacts}</div><div class="detail-seller-info"><div class="row">${avatar(s)}<div><h3>${e(s.name)}</h3><p class="muted small">${s.kind==='dealer'?'Дилер':'Частное лицо'}</p></div></div>${s.kind==='dealer'?`<a href="#/dealer/${e(s.id)}" class="text-link small">Все объявления продавца →</a>`:''}<hr><p class="small muted">${icon('pin')} ${e(a.city)}</p><p class="small muted mt">Добавлено ${date(a.created)}<br>Объявление №${e(a.id)}</p><div class="notice-box mt">Демо: контакты вымышлены, звонки и сообщения наружу не отправляются.</div></div></aside></div>`;
}
async function myAds(r){const tab=r.params.status||'all';const result=await call('my_ads',{status:tab,q:r.params.q||''});const tabs={all:'Все',active:'Активные',pending:'На проверке',draft:'Черновики',archived:'Архив'};
 const content=`<div class="between account-top"><h1>Мои объявления</h1>${linkButton('Разместить','/create','plus','primary')}</div><div class="tabs">${Object.entries(tabs).map(([key,label])=>`<a href="#${href('/account/ads',{status:key})}" class="tab ${tab===key?'active':''}">${label}<span class="count">${summary.counts[key]}</span></a>`).join('')}</div><form data-form="my-search" class="searchfield own-search">${icon('search')}<input name="q" value="${e(r.params.q)}" placeholder="Поиск по моим объявлениям" aria-label="Поиск по моим объявлениям"></form>${tab==='pending'?'<div class="notice-box amber mb">Решения принимает модератор. Для проверки сценария выберите Анну в меню «Сценарии демо».</div>':''}${result.ids.length?`<div class="stack">${result.ids.map(id=>{const a=ad(id);const chats=state.conversations.filter(c=>c.ad_id===id&&c.participants.includes(state.user_id));const unread=chats.reduce((n,c)=>n+(c.unread[state.user_id]||0),0);return `<article class="my-ad"><a class="mini-photo" href="#/ad/${id}">${photo(a)}</a><div><a href="#/ad/${id}"><h3>${e(a.title)}</h3><div class="price">${money(a.price)}</div></a><p class="spec-line">${specLine(a)}</p><p class="location">${icon('pin')}${e(a.city)||'Город не указан'}</p><div class="inline-status">${status(a)}${a.rejection?`<span class="danger small">${e(a.rejection)}</span>`:''}</div></div><div class="ad-actions">${['archived','sold'].includes(a.status)?button('Восстановить','restore','refresh','soft',`data-id="${id}"`):linkButton(a.status==='draft'?'Продолжить':'Редактировать',`/edit/${id}`,'edit',a.status==='draft'?'primary':'')}${chats.length?linkButton(`Сообщения${unread?` <span class="badge">${unread}</span>`:''}`,`/account/messages?chat=${chats[0].id}`,'chat',''):''}${ib('ad-menu','more','Действия с объявлением',`data-id="${id}"`)}</div></article>`;}).join('')}</div>`:empty(tab==='draft'?'Черновиков пока нет':'Здесь пока нет объявлений',r.params.q?'Измените запрос для поиска.':'Разместите первое объявление — незавершённую форму можно сохранить в черновики.',linkButton('Разместить объявление','/create','plus','primary'),'ads')}`;
 return account(content,'ads');
}
function favorites(){const rows=favs().map(ad).filter(a=>a&&a.status!=='deleted');return account(`<div class="between account-top"><h1>Избранное <span class="muted small">${rows.length}</span></h1>${linkButton(`Сравнить (${state.compare.length})`,'/compare','compare')}</div>${rows.length?`<div class="grid account-grid">${rows.map(card).join('')}</div>`:empty('Сохраните то, что понравилось','Нажмите на сердечко в карточке техники. Объявление появится здесь.',linkButton('В каталог','/catalog','search','primary'),'heart')}`,'favorites');}
function comparison(){const rows=state.compare.map(ad).filter(a=>a&&a.status!=='deleted');const keys=[['Цена',a=>money(a.price)],['Марка и модель',a=>a.title],['Тип техники',a=>meta.categories[a.category]],['Год выпуска',a=>a.year],['Пробег / наработка',mileage],['Колёсная формула',a=>a.wheels],['Коробка передач',a=>a.gearbox],['Мощность',a=>a.power?`${a.power} л. с.`:'Не указана'],['Город',a=>a.city],['НДС',a=>a.vat==='yes'?'С НДС':'Без НДС'],['Статус',a=>meta.statuses[a.status]]];return `<div class="breadcrumb"><a href="#/catalog">Каталог</a>${icon('chevron')}Сравнение</div><div class="page-head"><div class="row"><h1>Сравнение техники</h1><span class="muted">${rows.length} из 4</span></div>${rows.length?button('Очистить','clear-compare','trash','plain'):''}</div>${rows.length?`<div class="between mb wrap">${switcher('Только различия',ui.diff,'differences')}<a href="#/catalog" class="text-link small">Добавить технику из каталога →</a></div><div class="compare-scroll"><table class="compare-table" style="min-width:${190+rows.length*240}px"><thead><tr><th>Выберите до четырёх машин</th>${rows.map(a=>`<th><div class="between"><span>${e(a.brand)}</span>${ib('compare','close','Убрать из сравнения',`data-id="${a.id}"`)}</div><a href="#/ad/${a.id}">${photo(a)}<h3>${e(a.title)}</h3><div class="price">${money(a.price)}</div></a>${linkButton('Открыть объявление',`/ad/${a.id}`,'','soft w-full')}</th>`).join('')}</tr></thead><tbody>${keys.map(([label,fn])=>{const values=rows.map(fn),diff=new Set(values.map(String)).size>1;if(ui.diff&&!diff)return '';return `<tr class="${diff?'different':''}"><td>${label}</td>${values.map(v=>`<td>${e(v)}</td>`).join('')}</tr>`;}).join('')}</tbody></table></div>${ui.diff&&rows.length===1?'<p class="muted mt">Добавьте ещё одну машину, чтобы увидеть различия.</p>':''}`:empty('Пока нечего сравнивать','Нажмите значок сравнения на карточках техники. Можно выбрать до четырёх машин.',linkButton('Выбрать технику','/catalog','compare','primary'),'compare')}`;}
function searches(){const list=state.searches[state.user_id]||[];return account(`<div class="between account-top"><h1>Сохранённые поиски</h1>${linkButton('Новый поиск','/catalog','plus')}</div><p class="muted mb small">Все параметры поиска под рукой. Уведомления в демо сохраняются как настройки.</p>${list.length?`<div class="stack">${list.map(s=>`<article class="saved-card"><div class="between"><h3>${e(s.name)}</h3><div class="row gap-sm">${ib('edit-search','edit','Изменить поиск',`data-id="${s.id}"`)}${ib('delete-search','trash','Удалить поиск',`data-id="${s.id}"`)}</div></div><p class="saved-filters">${filterSummary(s.filters).map(x=>e(x.text)).join(' · ')||'Вся техника, вся Россия'}</p><div class="saved-controls">${switcher('Уведомления',s.notify,'search-notify',`data-id="${s.id}"`)}<select class="frequency" data-change="frequency" data-id="${s.id}" aria-label="Частота уведомлений">${options({instant:'Сразу',daily:'Раз в день',weekly:'Раз в неделю'},s.frequency)}</select>${button(`Смотреть${summary.search_new[s.id]?` <span class="count">${summary.search_new[s.id]} новых</span>`:''}`,'open-search','search','soft',`data-id="${s.id}"`)}</div></article>`).join('')}</div>`:empty('Ваши поиски будут здесь','Настройте фильтры в каталоге и нажмите «Сохранить поиск».',linkButton('Перейти в каталог','/catalog','search','primary'))}`,'searches');}
async function messages(r){const all=state.conversations.filter(c=>c.participants.includes(state.user_id));let selected=all.find(c=>c.id===r.params.chat);if(selected&&selected.unread[state.user_id]){await call('read_chat',{id:selected.id});selected=state.conversations.find(c=>c.id===selected.id);}
 const list=all.filter(c=>(seller(c.participants.find(p=>p!==state.user_id)).name+' '+(ad(c.ad_id)?.title||'')).toLowerCase().includes(ui.chatFilter.toLowerCase()));
 const inbox=`<div class="inbox"><div class="inbox-head"><input data-input="chat-search" value="${e(ui.chatFilter)}" placeholder="Имя или техника" aria-label="Поиск в сообщениях"></div>${list.length?list.map(c=>{const p=seller(c.participants.find(p=>p!==state.user_id));return `<a href="#/account/messages?chat=${c.id}" class="chat-row ${c.id===selected?.id?'active':''}">${avatar(p)}<div class="grow"><div class="between"><strong>${e(p.name)}</strong>${c.unread[state.user_id]?`<span class="badge">${c.unread[state.user_id]}</span>`:''}</div><p>${e(ad(c.ad_id)?.title||'Объявление удалено')}</p><p>${e(c.messages.at(-1)?.text||'Начните диалог')}</p></div></a>`;}).join(''):'<p class="muted small" style="padding:20px">Переписок пока нет</p>'}</div>`;
 let pane=empty('Выберите переписку','Здесь можно обсудить технику и договориться об осмотре.','','chat');
 if(selected){const a=ad(selected.ad_id),p=seller(selected.participants.find(p=>p!==state.user_id));pane=`<div class="chat-header"><div class="row"><a href="#/account/messages" class="icon-btn mobile-only" aria-label="Назад к сообщениям">${icon('back')}</a>${avatar(p)}<div class="grow"><strong>${e(p.name)}</strong><p class="small muted">Тестовая переписка</p></div>${a?ib('phone','phone','Контакт продавца',`data-id="${a.id}"`):''}</div>${a?`<a class="chat-ad" href="#/ad/${a.id}">${photo(a)}<div><b>${e(a.title)}</b><p class="muted">${money(a.price)} · ${e(a.city)}</p></div></a>`:''}</div><div class="chat-scroll">${selected.messages.length?selected.messages.map(m=>`<div class="bubble ${m.sender===state.user_id?'mine':''}"><div>${m.attachment?`<img src="${e(m.attachment)}" alt="Вложение">`:''}${e(m.text)}</div><time>${time(m.time)}${m.sender===state.user_id?' · доставлено в демо':''}</time></div>`).join(''):'<p class="muted small center">Поздоровайтесь и задайте вопрос о технике</p>'}</div>${ui.chatAttachment?`<div class="chat-attachment"><img src="${e(ui.chatAttachment)}" alt="Прикреплённое фото">${button('Убрать','remove-chat-photo','','plain sm')}</div>`:''}<form class="chat-compose" data-form="message" data-id="${selected.id}"><label class="icon-btn" aria-label="Прикрепить фото">${icon('clip')}<input type="file" accept="image/jpeg,image/png,image/webp" data-upload="chat" hidden></label><textarea name="text" placeholder="Напишите сообщение…" aria-label="Сообщение" maxlength="3000"></textarea><button type="submit" class="btn primary" aria-label="Отправить">${icon('send')}<span class="send-label">Отправить</span></button></form><button class="demo-reply" data-action="simulate-reply" data-id="${selected.id}">Демо: получить тестовый ответ собеседника</button>`;}
 return account(`<div class="between account-top"><h1>Сообщения</h1><span class="muted small">${all.length} ${plural(all.length,'диалог','диалога','диалогов')}</span></div><div class="messages-layout ${selected?'has-chat':''}">${inbox}<section class="chat-pane">${pane}</section></div>`,'messages');
}
function profile(){const u=user();return account(`<div class="account-top"><h1>Профиль и настройки</h1></div><form data-form="profile"><div class="profile-grid"><section class="panel"><h2>Личные данные</h2><div class="row mb">${avatar({...u,avatar:ui.profileAvatar||u.avatar},'large')}<div><label class="btn sm">${icon('photo')}Изменить фото<input type="file" accept="image/jpeg,image/png,image/webp" data-upload="avatar" hidden></label><p class="form-hint">JPG, PNG или WebP до 2 МБ</p></div></div>${field('name','Имя',u.name,'required minlength="2" maxlength="80" autocomplete="given-name"')}${selectField('kind','Тип аккаунта',{private:'Частное лицо',company:'Компания'},u.kind)}<div class="field-grid">${field('phone','Телефон',u.phone,'inputmode="tel"')}${field('email','Электронная почта',u.email,'type="email" autocomplete="email"')}</div>${selectField('city','Город',cities('Выберите город'),u.city)}<p class="form-hint">Контакты используются только внутри демо.</p></section><div class="stack"><section class="panel"><h2>Уведомления</h2>${[['messages','Сообщения','Ответы продавцов и покупателей'],['status','Объявления','Проверка и изменение статуса'],['searches','Сохранённые поиски','Новые предложения по вашим фильтрам']].map(([key,title,desc])=>`<div class="profile-notification"><div><strong>${title}</strong><p>${desc}</p></div><label class="switch"><input type="checkbox" name="notify_${key}" ${u.notifications[key]?'checked':''} aria-label="${title}"><span class="switch-track"></span></label></div>`).join('')}</section><section class="panel"><h2>Безопасность</h2><p class="muted small">Вход по коду из SMS. В демо код всегда <b>123456</b>.</p>${(state.sessions[state.user_id]||[{id:'current',name:'Этот браузер',current:true}]).map(s=>`<div class="session">${icon('laptop')}<span class="grow">${e(s.name)}</span>${s.current?'<span class="status active">Сейчас</span>':''}</div>`).join('')}${button('Завершить другие сеансы','end-sessions','','plain w-full mt')}${button('Выйти из аккаунта','logout','logout','plain danger w-full')}</section></div></div><div class="mt"><button type="submit" class="btn primary">Сохранить изменения</button></div></form>`,'profile');}
function help(){const tickets=state.tickets.filter(t=>t.user===state.user_id);return account(`<div class="account-top"><h1>Помощь</h1></div><div class="profile-grid"><section class="panel faq"><h2>Частые вопросы</h2>${[['Как разместить объявление?','Нажмите «Разместить», заполните три шага, проверьте предпросмотр и отправьте объявление на проверку. Незавершённую форму можно сохранить в черновики.'],['Как проверить модерацию?','В меню «Сценарии демо» выберите Анну — модератора. Проверьте объявление, опубликуйте его или верните с причиной. Продавец получит уведомление.'],['Как работает переписка?','Откройте чужое активное объявление и нажмите «Написать». Для проверки ответа есть кнопка «Получить тестовый ответ». Также можно переключаться между Азатом и Ильёй в меню демо.'],['Где сохраняются мои изменения?',window.TYAGA_SERVER?'В локальном файле tyaga.sqlite3. У каждого браузера своя сессия.':'В хранилище этого браузера. На другом устройстве откроется отдельное демо. Очистка данных браузера удалит изменения.'],['Как начать проверку сначала?','В верхней полосе нажмите «Сценарии демо» → «Сбросить демо». После подтверждения восстановятся исходные объявления и переписки.']].map(([q,a])=>`<details><summary>${q}</summary><p>${a}</p></details>`).join('')}</section><section class="panel"><h2 class="mb">Написать в поддержку</h2><form data-form="support">${selectField('topic','Тема',{'Вопрос об объявлении':'Вопрос об объявлении','Профиль и вход':'Профиль и вход','Сообщить об ошибке':'Сообщить об ошибке','Предложить улучшение':'Предложить улучшение'})}${selectField('ad_id','Объявление',{'':'Не относится к объявлению',...Object.fromEntries(state.ads.filter(a=>own(a)&&a.status!=='deleted').map(a=>[a.id,a.title]))})}<div class="field"><label for="support-text">Ваш вопрос</label><textarea id="support-text" name="text" required minlength="10" maxlength="3000" placeholder="Что произошло? Опишите подробнее…"></textarea></div><label class="btn plain small">${icon('clip')}${ui.supportAttachment?'Фото прикреплено':'Прикрепить скриншот'}<input type="file" accept="image/jpeg,image/png,image/webp" data-upload="support" hidden></label><p class="form-hint mb">Обращение сохранится в демо. Внешняя поддержка его не получит.</p><button type="submit" class="btn primary w-full">Отправить обращение</button></form>${tickets.length?`<h3 class="mt">Мои обращения</h3>${tickets.map(t=>`<article class="ticket"><div class="between"><b>№${t.number} · ${e(t.topic)}</b><span class="status">${e(t.status)}</span></div><p>${e(t.text)}</p><small class="muted">${date(t.time)}</small></article>`).join('')}`:''}</section></div>`,'help');}
async function dealers(r){const q=(r.params.q||'').toLowerCase();const list=state.sellers.filter(s=>(s.name+' '+s.city).toLowerCase().includes(q)&&(!r.params.city||s.city===r.params.city));return `<div class="page-head"><div class="row"><h1>Дилеры техники</h1><span class="muted">${list.length} компании</span></div></div><form class="searchbar" data-form="dealers"><div class="searchfield">${icon('search')}<input name="q" value="${e(r.params.q)}" placeholder="Название дилера или город" aria-label="Поиск дилеров"></div><select name="city" aria-label="Город дилера" style="max-width:220px">${options(cities('Все города'),r.params.city)}</select><button class="btn primary">Найти</button></form>${list.length?`<div class="dealer-grid">${list.map(s=>{const count=state.ads.filter(a=>a.owner===s.id&&a.status==='active').length;return `<article class="dealer-card"><div class="row">${avatar(s,'large')}<div><h2>${e(s.name)}</h2><p class="location">${icon('pin')}${e(s.city)}</p></div></div><p>${e(s.about)}</p><div class="between"><span class="muted small">${count} ${plural(count,'объявление','объявления','объявлений')}</span>${linkButton('Посмотреть технику',`/dealer/${s.id}`,'chevron','soft')}</div></article>`;}).join('')}</div>`:empty('Дилеры не найдены','Попробуйте другой город или название.',linkButton('Все дилеры','/dealers','refresh'))}`;}
async function dealer(r){const s=state.sellers.find(s=>s.id===r.parts[1]);if(!s)return empty('Дилер не найден','Посмотрите список доступных компаний.',linkButton('Дилеры','/dealers'));const result=await call('catalog',{owner:s.id,filters:{q:r.params.q||''}});return `<div class="breadcrumb"><a href="#/dealers">Дилеры</a>${icon('chevron')}${e(s.name)}</div><section class="dealer-head panel">${avatar(s)}<div class="grow"><h1>${e(s.name)}</h1><p>${icon('pin')} ${e(s.city)} · ${e(s.hours)}</p><p>${e(s.about)}</p></div></section><div class="between mb"><h2>Техника в наличии <span class="small muted">${result.ids.length}</span></h2></div><div class="grid">${result.ids.map(id=>card(ad(id))).join('')}</div>`;}
function editor(r){const key=r.path;if(ui.editorKey!==key){const existing=r.parts[0]==='edit'?ad(r.parts[1]):null;if(r.parts[0]==='edit'&&(!existing||!own(existing)))return empty('Объявление недоступно','Редактировать можно только свою технику.',linkButton('Мои объявления','/account/ads'));ui.editor=existing?structuredClone(existing):{section:'commercial',category:'tractor',brand:'',model:'',year:'',mileage:'',wheels:'4×2',gearbox:'Автомат',condition:'used',power:'',photos:[],description:'',price:'',city:user().city,vat:'no'};ui.editorKey=key;ui.step=1;ui.preview=false;}
 const a=ui.editor;const editing=!!a.id;
 if(ui.preview)return `<div class="form-shell"><div class="breadcrumb"><button class="text-link" data-action="back-editor">${icon('back')}Вернуться к редактированию</button></div><h1>Проверьте объявление</h1><p class="muted small mt mb">Так покупатели увидят вашу технику. После отправки объявление пройдёт проверку.</p><section class="panel"><div class="review-summary"><div>${photo(a)}</div><div><span class="status">Предпросмотр</span><h2 class="mt">${e(a.brand+' '+a.model)}</h2><div class="price">${money(a.price)}</div><p class="spec-line">${specLine(a)}</p><p class="location">${icon('pin')}${e(a.city)}</p><p class="small muted">${a.vat==='yes'?'С НДС':'Без НДС'}</p></div></div><div class="specs">${specs(a).slice(0,8).map(([k,v])=>`<div class="spec-item"><span>${k}</span><strong>${e(v)}</strong></div>`).join('')}</div><div class="review-details"><h3>Описание</h3><p class="description">${e(a.description)}</p></div></section><div class="sticky-actions">${button('Изменить','back-editor','edit')}${button('Отправить на проверку','publish','check','primary')}</div></div>`;
 let fields='';
 if(ui.step===1)fields=editorMainFields(a);
 if(ui.step===2)fields=`<h2>Фотографии и описание</h2><p class="muted">Добавьте до 8 фото. Первое будет обложкой объявления.</p>${a.photos.length?`<div class="photo-grid">${a.photos.map((src,i)=>`<div class="upload-photo"><img src="${e(src)}" alt="Фото ${i+1}">${ib('remove-photo','close','Удалить фото',`data-index="${i}"`)}<span>${i===0?'Обложка':`Фото ${i+1}`}</span></div>`).join('')}</div>`:''}<label class="upload-target">${icon('photo')}Добавить фотографии<small>JPG, PNG или WebP · до 2 МБ</small><input type="file" accept="image/jpeg,image/png,image/webp" multiple data-upload="ad" hidden></label>${button('Выбрать тестовое фото','demo-photo','photo','plain mt mb')}<div class="field"><label for="description">Описание</label><textarea id="description" name="description" minlength="10" maxlength="5000" required placeholder="Состояние техники, обслуживание, комплектация…">${e(a.description)}</textarea><p class="form-hint">Расскажите о состоянии и известных особенностях техники.</p></div>`;
 if(ui.step===3)fields=`<h2>Цена и место осмотра</h2><p class="muted">Покупатель сможет написать вам через сервис</p>${field('price','Цена, ₽',a.price,'required inputmode="numeric" placeholder="8 900 000"')}${selectField('vat','НДС',{no:'Без НДС',yes:'С НДС'},a.vat)}${selectField('city','Город',cities('Выберите город'),a.city,'required')}<div class="notice-box"><div class="row">${avatar(user())}<div><strong>${e(user().name)}</strong><p class="small">${e(user().phone)}</p></div></div><p class="small mt">Контакты можно изменить в профиле. В демо они вымышлены.</p></div>`;
 return `<div class="form-shell"><div class="breadcrumb"><a href="#/account/ads">${icon('back')}Мои объявления</a></div><div class="between"><h1>${editing?'Редактирование':'Новое объявление'}</h1><span class="muted small">Шаг ${ui.step} из 3</span></div><div class="wizard-steps">${['О технике','Фото и описание','Цена и контакты'].map((s,i)=>`<div class="wizard-step ${i+1<=ui.step?'active':''}"><span>${i+1<ui.step?'✓':i+1}</span>${s}</div>`).join('')}</div><form class="wizard-form panel" data-form="editor"><div id="editor-errors"></div>${fields}<div class="form-actions">${button('Сохранить черновик','save-draft','','plain')}${ui.step>1?button('Назад','editor-back','back'):''}<button type="submit" class="btn primary">${ui.step===3?'Предпросмотр':'Далее'}${icon(ui.step===3?'eye':'chevron')}</button></div></form></div>`;
}
function loginPage(){return `<div class="form-shell">${empty('Войдите в личный кабинет','Управляйте объявлениями, сохраняйте технику и общайтесь с продавцами.',button('Войти по телефону','login','user','primary')+button('Демо: войти как Азат','demo-user','','soft','data-user="azat"'),'user')}</div>`;}
async function render(){const token=++renderToken;const r=route();try{let content;const p=r.parts[0];if(['account','create','edit'].includes(p)&&!user())content=loginPage();else if(p==='catalog'||!p)content=await catalog(r);else if(p==='moderator')content=await moderation(r);else if(p==='ad')content=detail(ad(r.parts[1]));else if(p==='compare')content=comparison();else if(p==='dealers')content=await dealers(r);else if(p==='dealer')content=await dealer(r);else if(p==='create'||p==='edit')content=editor(r);else if(p==='account'){const pages={ads:()=>myAds(r),favorites,searches,messages:()=>messages(r),profile,help};content=await(pages[r.parts[1]]||pages.ads)();}else content=empty('Страница не найдена','Вернитесь в каталог техники.',linkButton('Каталог','/catalog','search','primary'));if(token!==renderToken)return;$('#app').innerHTML=shell(content,r);document.title=(p==='moderator'?'Кабинет модератора':p==='account'?'Личный кабинет':p==='ad'?ad(r.parts[1])?.title||'Объявление':'Транспорт и спецтехника')+' — ТЯГА';const sc=$('.chat-scroll');if(sc)sc.scrollTop=sc.scrollHeight;const queue=$('.review-queue-items');if(queue&&ui.reviewQueueScroll)queue.scrollTop=ui.reviewQueueScroll;}catch(err){if(token!==renderToken)return;fail(err);if(state)$('#app').innerHTML=shell(empty('Не удалось открыть страницу',e(err.message),linkButton('В каталог','/catalog','refresh','primary')),r);}}

function openLogin(step='phone'){
 if(step==='code'){showModal('Введите код',`<p class="muted mb">Код для ${e(state.challenge?.phone||'вашего номера')}.</p><div class="notice-box mb">Демо-код: <b>123456</b>. SMS не отправляется.</div><form data-form="verify"><div class="field"><label for="code">Код из 6 цифр</label><input id="code" name="code" class="code-input" inputmode="numeric" autocomplete="one-time-code" pattern="[0-9]{6}" maxlength="6" placeholder="000000" required></div><button type="submit" class="btn primary w-full">Войти</button></form>${button('Изменить номер','login','','plain w-full mt')}`);return;}
 showModal('Вход в ТЯГУ',`<p class="muted mb">Ваши объявления, избранное и сообщения в одном месте.</p><form data-form="login">${field('phone','Номер телефона','','type="tel" inputmode="tel" autocomplete="tel" placeholder="+7 999 123-45-67" required')}<button class="btn primary w-full" type="submit">Получить код</button></form><p class="form-hint mt">Тестовый вход: подойдет любой корректный номер. Код — 123456, SMS не отправляется.</p><hr><p class="small muted">Или сразу выберите тестовый аккаунт</p><div class="auth-options">${button('Азат · продавец','demo-user','','soft','data-user="azat"')}${button('Илья · покупатель','demo-user','','','data-user="ilya"')}</div>`);
}
function demoPanel(){showModal('Проверьте все сценарии',`<p class="muted mb">Все действия остаются внутри демо. Можно свободно редактировать и удалять тестовые данные.</p><div class="auth-options mb">${button('Азат · продавец','demo-user','user',state.user_id==='azat'?'primary':'','data-user="azat"')}${button('Илья · покупатель','demo-user','user',state.user_id==='ilya'?'primary':'','data-user="ilya"')}${button('Анна · модератор','demo-user','shield',isModerator()?'primary':'','data-user="moderator"')}</div><div class="demo-grid">${[['/catalog','search','Подобрать технику','Поиск, фильтры, сортировка'],['/account/ads','ads','Управлять объявлениями','Все статусы, архив и удаление'],['/create','plus','Разместить объявление','Три шага и предпросмотр'],['/moderator','shield','Кабинет модератора','Очередь, решения и история проверок'],['/account/messages','chat','Проверить сообщения','Диалоги, вложения, тестовый ответ'],['/compare','compare','Сравнить технику','До четырёх машин и различия'],['/account/searches','bell','Сохранённые поиски','Новые результаты и уведомления'],['/account/profile','settings','Настроить аккаунт','Профиль и тестовые сеансы'],['/account/help','help','Обратиться в поддержку','Форма обращения и история'],['/dealers','building','Посмотреть дилеров','Поиск компании и её техника']].map(([path,i,t,d])=>`<a href="#${path}" class="demo-scenario" data-close="true">${icon(i)}<div><strong>${t}</strong><p>${d}</p></div></a>`).join('')}</div><hr><div class="between wrap">${button('Сбросить демо','reset-demo','refresh','danger')}</div><p class="form-hint mt">${window.TYAGA_SERVER?'Данные сохраняются в SQLite на этом компьютере.':'Данные сохраняются в этом браузере. На другом устройстве будет отдельное демо.'}</p>`,'wide');}
function openSearchModal(id){if(!user()){openLogin();return;}const s=(state.searches[state.user_id]||[]).find(s=>s.id===id);const f=s?s.filters:route().params;showModal(s?'Изменить поиск':'Сохранить поиск',`<form data-form="save-search" data-id="${e(s?.id||'')}">${field('name','Название',s?.name||filterSummary(f).slice(0,2).map(x=>x.text).join(' · ')||'Мой поиск','required maxlength="100"')}${s?`<div class="filter-fields">${filterFields(f,true)}</div>`:`<p class="notice-box mb">${filterSummary(f).map(x=>e(x.text)).join(' · ')||'Вся техника, вся Россия'}</p>`}${selectField('frequency','Уведомления',{instant:'Сразу',daily:'Раз в день',weekly:'Раз в неделю'},s?.frequency||'daily')}<label class="check mb"><input type="checkbox" name="notify" ${s?.notify===false?'':'checked'}>Уведомлять о новых объявлениях</label><button type="submit" class="btn primary w-full">Сохранить поиск</button></form>`);}
function confirmation(title,text,action,id='',extra=''){showModal(title,`<p class="muted">${text}</p><div class="modal-actions">${button('Отмена','close')}${button('Подтвердить',action,'','primary',`data-id="${e(id)}" ${extra}`)}</div>`);}
function openGallery(id,index=0){const a=ad(id);if(!a?.photos.length){toast('Добавьте фотографии в объявление');return;}ui.galleryAd=id;ui.galleryIndex=(index+a.photos.length)%a.photos.length;showModal(e(a.title),`<img src="${e(a.photos[ui.galleryIndex])}" alt="${e(a.title)}, фото ${ui.galleryIndex+1}" data-action="zoom" style="cursor:zoom-in">${a.photos.length>1?`${ib('gallery-prev','back','Предыдущее фото','','arrow prev')}${ib('gallery-next','chevron','Следующее фото','','arrow next')}`:''}<div class="lightbox-caption">${ui.galleryIndex+1} / ${a.photos.length} · Нажмите на фото, чтобы увеличить</div>`,'lightbox');}
function collectEditor(){const form=$('form[data-form="editor"]');if(form)Object.assign(ui.editor,formValues(form));}
function editorError(err){const target=$('#editor-errors');if(target){target.innerHTML=`<div class="form-error" role="alert">${e(err.message)}${Object.values(err.fields||{}).length>1?`<br>${Object.values(err.fields).map(e).join(' · ')}`:''}</div>`;target.scrollIntoView({block:'center',behavior:'smooth'});}else fail(err);}
async function mutate(action,payload={},message=''){const result=await call(action,payload);closeModal();await render();if(message||result.message)toast(message||result.message);return result;}
async function clickAction(target){const {action,id}=target.dataset;const r=route();
 if(action.startsWith('review-')||action==='moderator-remove'){if(await reviewAction(target))return;}
 if(action==='close')return closeModal();
 if(action==='login')return openLogin();
 if(action==='demo')return demoPanel();
 if(action==='demo-user'){await call('demo_user',{user:target.dataset.user});ui.editorKey=null;ui.profileAvatar=null;ui.chatAttachment=null;closeModal();go(isModerator()?'/moderator':'/account/ads');toast('Вы вошли как '+user().name);return;}
 if(action==='logout'){await call('logout');ui.editorKey=null;closeModal();go('/catalog');return;}
 if(action==='favorite'){await call('favorite',{id});await render();toast(favs().includes(id)?'Добавлено в избранное':'Убрано из избранного');return;}
 if(action==='compare'){await call('compare_toggle',{id});await render();toast(state.compare.includes(id)?`В сравнении ${state.compare.length} из 4`:'Убрано из сравнения');return;}
 if(action==='clear-compare')return confirmation('Очистить сравнение?','Вы сможете добавить технику снова.','confirm-clear-compare');
 if(action==='confirm-clear-compare')return mutate('compare_clear',{},'Сравнение очищено');
 if(action==='section')return go('/catalog',{...resetDependent(r.params,'section'),section:target.dataset.section});
 if(action==='category')return go('/catalog',{...resetDependent(r.params,'category'),category:target.dataset.category,section:meta.category_sections[target.dataset.category]||sectionOf(r.params)});
 if(action==='view'){ui.view=target.dataset.view;return render();}
 if(action==='reset-filters')return go('/catalog');
 if(action==='remove-filter'){const f={...r.params};delete f[target.dataset.key];if(target.dataset.key==='city'){delete f.radius;if(f.sort==='distance')delete f.sort;}if(['section','category'].includes(target.dataset.key))return go('/catalog',resetDependent(f,target.dataset.key));return go('/catalog',f);}
 if(action==='filters')return showModal('Фильтры',`<form data-form="filters" class="filter-panel"><div class="filter-fields">${filterFields(r.params)}</div><div class="form-actions filter-submit">${button('Сбросить','reset-filters','','plain')}<button class="btn primary" type="submit">Показать объявления</button></div></form>`);
 if(action==='location')return showModal('Где искать технику?',`<form data-form="location">${selectField('city','Город',cities('Вся Россия'),r.params.city)}${selectField('radius','Радиус',{'0':'Только этот город','100':'+100 км','250':'+250 км','500':'+500 км','1000':'+1 000 км'},r.params.radius||0)}<button class="btn primary w-full" type="submit">Показать технику</button></form>`);
 if(action==='share-search'){try{await navigator.clipboard.writeText(location.href);toast('Ссылка на поиск скопирована');}catch{showModal('Ссылка на поиск',`<input value="${e(location.href)}" aria-label="Ссылка на поиск" readonly onclick="this.select()">`);}return;}
 if(action==='search-suggestion')return go('/catalog',{...resetDependent(r.params,'section'),q:target.dataset.q,section:target.dataset.section,category:target.dataset.category});
 if(action==='save-search'||action==='edit-search')return openSearchModal(id);
 if(action==='delete-search')return confirmation('Удалить сохранённый поиск?','Его параметры и настройки уведомлений будут удалены.','confirm-delete-search',id);
 if(action==='confirm-delete-search')return mutate('delete_search',{id},'Поиск удалён');
 if(action==='open-search'){const s=(state.searches[state.user_id]||[]).find(s=>s.id===id);await call('search_seen',{id});return go('/catalog',s.filters);}
 if(action==='start-chat'){const result=await call('start_chat',{id});return go('/account/messages',{chat:result.id});}
 if(action==='simulate-reply'){await call('simulate_reply',{id});return render();}
 if(action==='remove-chat-photo'){ui.chatAttachment=null;return render();}
 if(action==='phone')return showModal('Контакт продавца',`<div class="row mb">${avatar(seller(ad(id).owner))}<div><h3>${e(seller(ad(id).owner).name)}</h3><p class="muted small">${e(ad(id).title)}</p></div></div><p style="font-size:25px;font-weight:700">+7 ••• ••• 00 00</p><div class="notice-box mt">Это вымышленный контакт для проверки сценария. Позвонить из демо нельзя.</div>${!own(ad(id))&&ad(id).status==='active'?button('Написать в демо','start-chat','chat','primary w-full mt',`data-id="${id}"`):''}`);
 if(action==='ad-menu'){const a=ad(id);return showModal(e(a.title),`<div class="ad-menu">${linkButton('Открыть объявление',`/ad/${id}`,'eye')}${linkButton('Редактировать',`/edit/${id}`,'edit')}${a.status==='active'?button('Отметить как проданное','ask-sold','check','',`data-id="${id}"`):''}${!['archived','sold'].includes(a.status)?button('Снять с публикации в архив','ask-archive','archive','',`data-id="${id}"`):button('Вернуть в каталог','restore','refresh','',`data-id="${id}"`)}${button('Удалить объявление','ask-delete-ad','trash','danger',`data-id="${id}"`)}</div>`);}
 if(action.startsWith('ask-')){const kind=action.slice(4);const title={sold:'Техника продана?',archive:'Переместить в архив?','delete-ad':'Удалить объявление?'}[kind];return confirmation(title,kind==='delete-ad'?'Объявление исчезнет из вашего списка. Исходные данные можно вернуть через сброс демо.':'Объявление исчезнет из каталога. При необходимости его можно восстановить из архива.','confirm-'+kind,id);}
 if(action==='confirm-sold'||action==='confirm-archive'||action==='confirm-delete-ad')return mutate({'confirm-sold':'sold','confirm-archive':'archive','confirm-delete-ad':'delete_ad'}[action],{id});
 if(action==='restore')return mutate('restore',{id});
 if(action==='end-sessions')return confirmation('Завершить другие сеансы?','Текущий сеанс останется активным.','confirm-end-sessions');
 if(action==='confirm-end-sessions')return mutate('end_sessions');
 if(action==='reset-demo')return confirmation('Начать проверку сначала?','Ваши изменения в этом демо будут заменены исходными объявлениями, сообщениями и настройками.','confirm-reset');
 if(action==='confirm-reset'){await call('reset');ui.editorKey=null;ui.chatAttachment=null;ui.profileAvatar=null;closeModal();go('/catalog');toast('Исходные данные восстановлены');return;}
 if(action==='gallery')return openGallery(id,Number(target.dataset.index)||0);
 if(action==='gallery-prev')return openGallery(ui.galleryAd,ui.galleryIndex-1);
 if(action==='gallery-next')return openGallery(ui.galleryAd,ui.galleryIndex+1);
 if(action==='zoom'){target.classList.toggle('zoomed');return;}
 if(action==='notices'){if(!user())return openLogin();const notes=state.notices.filter(n=>n.user===state.user_id);showModal('Уведомления',notes.length?notes.map(n=>`<article class="modal-notice"><strong>${!n.read?'<span class="alert-dot"></span>':''}${e(n.title)}</strong><p>${e(n.text)}</p><time>${date(n.time)} · ${time(n.time)}</time>${n.ad_id&&ad(n.ad_id)?.status!=='deleted'?`<p><a class="text-link" href="#/ad/${e(n.ad_id)}" data-close="true">Открыть объявление →</a></p>`:''}</article>`).join(''):'<p class="muted">Новых уведомлений пока нет</p>');await call('read_notices');await render();return;}
 if(action==='save-draft'){collectEditor();try{const result=await call('save_ad',{ad:ui.editor,status:'draft'});ui.editorKey=null;go('/account/ads',{status:'draft'});toast(result.message);}catch(err){editorError(err);}return;}
 if(action==='editor-back'){collectEditor();ui.step=Math.max(1,ui.step-1);return render();}
 if(action==='back-editor'){ui.preview=false;ui.step=3;return render();}
 if(action==='demo-photo'){collectEditor();return showModal('Выберите фото для демо',`<p class="muted mb">Можно добавить своё фото или использовать одно из тестовых.</p><div class="asset-picker">${Object.entries(assets).map(([key,label])=>`<button data-action="pick-photo" data-asset="${key}"><img src="/assets/${key}.webp" alt="${e(label)}"><span>${e(label)}</span></button>`).join('')}</div>`);}
 if(action==='pick-photo'){if(ui.editor.photos.length>=8)throw new Error('Можно добавить до 8 фотографий');ui.editor.photos.push('/assets/'+target.dataset.asset+'.webp');ui.editor.asset=target.dataset.asset;closeModal();return render();}
 if(action==='remove-photo'){collectEditor();ui.editor.photos.splice(Number(target.dataset.index),1);return render();}
 if(action==='publish'){const result=await call('save_ad',{ad:ui.editor,status:'pending'});ui.editorKey=null;go('/account/ads',{status:'pending'});toast(result.message);return;}
}
async function submitForm(form,submitter){const kind=form.dataset.form,d=formValues(form),r=route();
 if(await reviewSubmit(form,submitter))return;
 if(kind==='moderation-search')return go('/moderator',{status:r.params.status||'pending',...d});
 if(kind==='search')return go('/catalog',{...r.params,q:d.q});
 if(kind==='filters')return go('/catalog',{q:r.params.q||'',sort:r.params.sort||'new',...d});
 if(kind==='location')return go('/catalog',{...r.params,...d});
 if(kind==='my-search')return go('/account/ads',{status:r.params.status||'all',q:d.q});
 if(kind==='dealers')return go('/dealers',d);
 if(kind==='login'){await call('request_code',d);return openLogin('code');}
 if(kind==='verify'){await call('verify_code',d);closeModal();await render();toast('Вы вошли как Азат');return;}
 if(kind==='save-search'){const id=form.dataset.id;const old=(state.searches[state.user_id]||[]).find(s=>s.id===id);const filters=old?d:r.params;await call('save_search',{id:id||null,name:d.name,filters,notify:!!d.notify,frequency:d.frequency});closeModal();go('/account/searches');toast('Поиск сохранён');return;}
 if(kind==='profile'){const notifications=Object.fromEntries(['messages','status','searches'].map(k=>[k,!!d['notify_'+k]]));await call('profile',{...d,notifications,avatar:ui.profileAvatar||undefined});ui.profileAvatar=null;await render();toast('Профиль сохранён');return;}
 if(kind==='support'){const result=await call('support',{...d,attachment:ui.supportAttachment});ui.supportAttachment=null;await render();showModal('Обращение принято',`<div class="empty-icon" style="margin:0 auto 20px">${icon('check')}</div><h2 class="center">№${result.number}</h2><p class="muted center mt">Обращение сохранено в истории. Это тестовая заявка, она не отправляется внешней поддержке.</p>${button('Понятно','close','','primary w-full mt')}`);return;}
 if(kind==='message'){await call('send_message',{id:form.dataset.id,text:d.text,attachment:ui.chatAttachment});ui.chatAttachment=null;await render();$('.chat-compose textarea')?.focus();return;}
 if(kind==='editor'){collectEditor();if(ui.step===2&&!ui.editor.photos.length){editorError(new Error('Добавьте хотя бы одну фотографию'));return;}if(ui.step<3){ui.step++;await render();window.scrollTo({top:0});}else{try{const result=await call('validate_ad',{ad:ui.editor});ui.editor={...ui.editor,...result.ad,id:ui.editor.id};ui.preview=true;await render();window.scrollTo({top:0});}catch(err){editorError(err);}}return;}
}
async function upload(input){const files=[...input.files];if(!files.length)return;for(const f of files)if(!['image/jpeg','image/png','image/webp'].includes(f.type)||f.size>2*1024*1024)throw new Error('Выберите JPG, PNG или WebP до 2 МБ');const values=await Promise.all(files.map(f=>new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(r.result);r.onerror=()=>reject(new Error('Не удалось прочитать файл'));r.readAsDataURL(f);})));const type=input.dataset.upload;if(type==='ad'){collectEditor();if(ui.editor.photos.length+values.length>8)throw new Error('Можно добавить до 8 фотографий');ui.editor.photos.push(...values);await render();}if(type==='chat'){ui.chatAttachment=values[0];const text=$('.chat-compose textarea')?.value;await render();if($('.chat-compose textarea'))$('.chat-compose textarea').value=text||'';}if(type==='avatar'){ui.profileAvatar=values[0];const img=$('form[data-form="profile"] .avatar');if(img)img.innerHTML=`<img src="${e(values[0])}" alt="Фото профиля">`;toast('Фото добавлено. Сохраните изменения.');}if(type==='support'){ui.supportAttachment=values[0];const label=input.closest('label');label.childNodes.forEach(n=>{if(n.nodeType===3)n.textContent='Фото прикреплено';});toast('Фото прикреплено');}}
document.addEventListener('click',event=>{const target=event.target.closest('[data-action]');if(target){event.preventDefault();if(target.disabled)return;target.disabled=true;Promise.resolve(clickAction(target)).catch(fail).finally(()=>{if(target.isConnected)target.disabled=false;});return;}if(event.target.matches('.modal-backdrop'))closeModal();if(event.target.closest('a[href^="#"]')){if(route().parts[0]==='catalog')ui.catalogReturn={hash:location.hash,scroll:window.scrollY};closeModal();}});
document.addEventListener('submit',event=>{const form=event.target.closest('[data-form]');if(!form)return;event.preventDefault();const submit=event.submitter;if(submit)submit.disabled=true;Promise.resolve(submitForm(form,submit)).catch(fail).finally(()=>{if(submit?.isConnected)submit.disabled=false;});});
document.addEventListener('change',event=>{const t=event.target;let work;if(t.hasAttribute('data-review-auto-next')){ui.reviewAutoNext=t.checked;return;}if(t.dataset.reviewCheck){const form=t.form,a=ad(form.dataset.id),checks=Object.fromEntries(['photos','details','description'].map(k=>[k,!!form.querySelector('[name=check_'+k+']')?.checked]));storeReviewDraft(a,{checks});form.querySelector('.review-progress').textContent=Object.values(checks).filter(Boolean).length+' из 3';return;}if(t.dataset.upload)work=upload(t);else if(t.dataset.change==='sort')work=go('/catalog',{...route().params,sort:t.value});else if(t.dataset.change==='differences'){ui.diff=t.checked;work=render();}else if(t.dataset.change==='search-notify')work=call('search_preferences',{id:t.dataset.id,notify:t.checked}).then(()=>toast('Настройка сохранена'));else if(t.dataset.change==='frequency')work=call('search_preferences',{id:t.dataset.id,frequency:t.value}).then(()=>toast('Частота сохранена'));else if(t.closest('[data-form="editor"]')&&['section','category','fuel','equipment_type'].includes(t.name)){collectEditor();if(t.name==='section'){ui.editor.category=Object.keys(meta.category_groups[t.value])[0];ui.editor.section=t.value;}if(t.name==='category')ui.editor.section=meta.category_sections[t.value];if(['section','category'].includes(t.name)){for(const f of meta.fields)delete ui.editor[f.key];delete ui.editor.mileage;delete ui.editor.hours;}work=render();}else if(t.closest('[data-form="filters"],[data-form="save-search"]')){const form=t.closest('form');let f=formValues(form);if(['section','category','fuel','equipment_type','brand'].includes(t.name)){if(['section','category'].includes(t.name))f=resetDependent(f,t.name);if(t.name==='brand')delete f.model;const container=form.querySelector('.filter-fields');if(container){container.innerHTML=filterFields(f);for(const details of container.querySelectorAll('.filter-details'))if(t.name==='fuel'||t.name==='equipment_type')details.open=true;}}if(form.dataset.form==='filters')work=updateFilterCount(form);}Promise.resolve(work).catch(fail);});
let inputTimer,searchTimer,filterTimer;document.addEventListener('input',event=>{if(event.target.dataset.reviewDraft){const a=ad(event.target.form?.dataset.id);if(a)storeReviewDraft(a,{[event.target.dataset.reviewDraft]:event.target.value});}if(event.target.dataset.input==='catalog-search'){clearTimeout(searchTimer);searchTimer=setTimeout(()=>updateSuggestions(event.target).catch(fail),180);}if(event.target.closest('[data-form="filters"]')){clearTimeout(filterTimer);const form=event.target.form;filterTimer=setTimeout(()=>updateFilterCount(form),250);}if(event.target.dataset.input==='chat-search'){ui.chatFilter=event.target.value;const caret=event.target.selectionStart;clearTimeout(inputTimer);inputTimer=setTimeout(async()=>{await render();const input=$('[data-input="chat-search"]');input?.focus();input?.setSelectionRange(caret,caret);},200);}});
document.addEventListener('keydown',event=>{if(route().parts[0]==='moderator'&&isModerator()&&!$('.modal')&&!event.ctrlKey&&!event.metaKey&&!event.altKey&&!event.target.closest('input,textarea,select,[contenteditable=true]')&&['j','k','о','л'].includes(event.key.toLowerCase())){event.preventDefault();const forward=['j','о'].includes(event.key.toLowerCase());navigateReview(ui.reviewIds?.[ui.reviewIds.indexOf(ui.reviewSelected)+(forward?1:-1)]);return;}if(event.key==='Escape'){closeModal();const box=$('#search-suggestions');if(box){box.hidden=true;$('[data-input="catalog-search"]')?.setAttribute('aria-expanded','false');}return;}if(['ArrowDown','ArrowUp'].includes(event.key)&&(event.target.dataset.input==='catalog-search'||event.target.closest('#search-suggestions'))){const list=$$('#search-suggestions button');if(list.length){event.preventDefault();const index=list.indexOf(document.activeElement);list[(index+(event.key==='ArrowDown'?1:-1)+list.length)%list.length]?.focus();}}if(event.target.matches('.chat-compose textarea')&&event.key==='Enter'&&!event.shiftKey&&!event.isComposing){event.preventDefault();event.target.form.requestSubmit();}if($('.lightbox')&&['ArrowLeft','ArrowRight'].includes(event.key)){event.preventDefault();openGallery(ui.galleryAd,ui.galleryIndex+(event.key==='ArrowLeft'?-1:1));}if(event.key==='Tab'&&$('.modal')){const elements=$$('a[href],button:not([disabled]),input:not([hidden]),select,textarea',$('.modal')).filter(x=>x.offsetParent!==null);const first=elements[0],last=elements.at(-1);if(event.shiftKey&&document.activeElement===first){event.preventDefault();last?.focus();}else if(!event.shiftKey&&document.activeElement===last){event.preventDefault();first?.focus();}}});
window.addEventListener('hashchange',async()=>{closeModal();ui.chatAttachment=null;await render();if(route().parts[0]==='catalog'&&ui.catalogReturn?.hash===location.hash)window.scrollTo({top:ui.catalogReturn.scroll});else if(route().parts[0]==='moderator'&&route().params.id&&window.innerWidth<900)$('#moderation-detail')?.scrollIntoView({block:'start'});else window.scrollTo({top:0});});
window.addEventListener('unhandledrejection',event=>{event.preventDefault();fail(event.reason||new Error('Не удалось выполнить действие'));});
const sectionOf = f => f.section || meta.category_sections[f.category] || '';
const isModerator = () => user()?.role === 'moderator';
const hourTypes = ['excavator','loader','construction','farm','warehouse','snowmobile','motorboat','boat','yacht','jetski'];
function meterFor(category){return ['trailer','rowing'].includes(category)?null:hourTypes.includes(category)?'hours':'mileage';}
function applicableFields(f){const section=sectionOf(f);return meta.fields.filter(x=>{
 if(!x.sections.includes(section)&&!x.categories.includes(f.category))return false;
 const w=x.when;if(!w)return true;
 if(w.not)return Object.entries(w.not).every(([k,v])=>f[k]!==v);
 return Object.entries(w).every(([k,v])=>f[k]===v);
});}
function formValues(form){const fd=new FormData(form),result={};for(const k of new Set(fd.keys()))result[k]=fd.getAll(k).join(',');return result;}
function resetDependent(f,kind){const next={...f};for(const x of meta.fields){delete next[x.key];delete next['min_'+x.key];delete next['max_'+x.key];}delete next.max_mileage;delete next.max_hours;delete next.brand;delete next.model;if(kind==='section')delete next.category;return next;}
function multiField(name,label,values,value=''){
 const selected=String(value||'').split(',').filter(Boolean),all=[...new Set([...values,...selected])].sort((a,b)=>a.localeCompare(b,'ru'));
 return `<div class="field"><span class="field-label">${label}</span><details class="multi-select"><summary>${selected.length?e(selected.join(', ')):'Любая '+(name==='brand'?'марка':'модель')}</summary><div class="multi-options">${all.length?all.map(v=>`<label class="check"><input type="checkbox" name="${name}" value="${e(v)}" ${selected.includes(v)?'checked':''}>${e(v)}</label>`).join(''):'<p class="form-hint">Сначала выберите марку</p>'}</div></details></div>`;
}
function rangeField(key,label,f,unit=''){
 return `<div class="field"><span class="field-label">${e(label)}${unit?', '+e(unit):''}</span><div class="field-grid"><input name="min_${key}" value="${e(f['min_'+key])}" inputmode="decimal" placeholder="От" aria-label="${e(label)} от"><input name="max_${key}" value="${e(f['max_'+key])}" inputmode="decimal" placeholder="До" aria-label="${e(label)} до"></div></div>`;
}
let filterSerial=0;
function filterFields(f={},extra=false){
 const section=sectionOf(f),cats=section?meta.category_groups[section]:meta.categories;
 const rows=state.ads.filter(a=>a.status==='active'&&(!section||a.section===section)&&(!f.category||a.category===f.category));
 const brands=[...new Set(rows.map(a=>a.brand))],selectedBrands=String(f.brand||'').split(',');
 const models=f.brand?[...new Set(rows.filter(a=>selectedBrands.includes(a.brand)).map(a=>a.model))]:[];
 const fields=applicableFields({...f,section});
 const meter=meterFor(f.category);
 let html=`${extra?field('q','Ключевые слова',f.q,'placeholder="Марка, модель или тип"'):''}${selectField('section','Раздел',{'':'Весь транспорт',...meta.sections},section)}${selectField('category','Категория',{'':'Все категории',...cats},f.category)}${multiField('brand','Марка',brands,f.brand)}${multiField('model','Модель',models,f.model)}${rangeField('price','Цена',f,'₽')}<div class="field"><span class="field-label">Год выпуска</span><div class="field-grid"><input name="year_from" value="${e(f.year_from)}" inputmode="numeric" placeholder="От" aria-label="Год от"><input name="year_to" value="${e(f.year_to)}" inputmode="numeric" placeholder="До" aria-label="Год до"></div></div>${selectField('condition','Состояние',{'':'Любое',new:'Новое',used:'Б/у'},f.condition)}${selectField('city','Город',cities('Вся Россия'),f.city)}${selectField('radius','Радиус',{'0':'Только этот город','100':'+100 км','250':'+250 км','500':'+500 км','1000':'+1 000 км'},f.radius||0)}`;
 if(f.category&&meter)html+=field(meter==='hours'?'max_hours':'max_mileage',meter==='hours'?'Наработка до, м/ч':'Пробег до, км',f[meter==='hours'?'max_hours':'max_mileage'],'inputmode="numeric" placeholder="Не важно"');
 else if(section==='cars'||section==='moto')html+=field('max_mileage','Пробег до, км',f.max_mileage,'inputmode="numeric" placeholder="Не важно"');
 html+=`${fields.length?`<details class="filter-details" ${fields.some(x=>f[x.key]||f['min_'+x.key]||f['max_'+x.key])?'open':''}><summary>Характеристики <span>${fields.length}</span></summary><div class="filter-details-body">${fields.map(x=>x.type==='select'?selectField(x.key,x.label,{'':'Не важно',...x.options},f[x.key]):rangeField(x.key,x.label,f,x.unit)).join('')}</div></details>`:`<p class="form-hint mb">Выберите категорию, чтобы открыть её характеристики.</p>`}<details class="filter-details" ${f.seller_kind||f.availability||f.age_days||f.vat||f.only_photo||f.include_unknown?'open':''}><summary>Условия продажи</summary><div class="filter-details-body">${selectField('seller_kind','Продавец',{'':'Любой',private:'Частное лицо',company:'Компания'},f.seller_kind)}${selectField('availability','Наличие',{'':'Любое',stock:'В наличии',order:'Под заказ'},f.availability)}${selectField('age_days','Опубликовано',{'':'За всё время',1:'За сутки',7:'За неделю',30:'За месяц'},f.age_days)}${selectField('vat','НДС',{'':'Не важно',yes:'С НДС',no:'Без НДС'},f.vat)}<label class="check mb"><input type="checkbox" name="only_photo" ${f.only_photo?'checked':''}>Только с фото</label><label class="check"><input type="checkbox" name="include_unknown" ${f.include_unknown?'checked':''}>Включать неизвестные значения</label><p class="form-hint">Для числовых фильтров. Пустое значение не считается нулём.</p></div></details>`;
 const prefix='f'+(++filterSerial)+'-';return html.replaceAll('id="f-','id="'+prefix).replaceAll('for="f-','for="'+prefix);
}
function filterSummary(f){
 const labels={q:'Поиск',section:'',category:'',brand:'',model:'',city:'',min_price:'Цена от',max_price:'Цена до',year_from:'Год от',year_to:'Год до',condition:'Состояние',vat:'',radius:'Радиус',max_mileage:'Пробег до',max_hours:'Наработка до',seller_kind:'Продавец',availability:'',age_days:'За дней',only_photo:'Только с фото',include_unknown:'С неизвестными значениями'};
 for(const x of meta.fields){labels[x.key]=x.label;labels['min_'+x.key]=x.label+' от';labels['max_'+x.key]=x.label+' до';}
 return Object.entries(f).filter(([k,v])=>k in labels&&v!==''&&v!=null&&!(k==='radius'&&!Number(v))).map(([k,v])=>{
 let val=k==='section'?meta.sections[v]:k==='category'?meta.categories[v]:k==='condition'?(v==='new'?'Новое':'Б/у'):k==='vat'?(v==='yes'?'С НДС':'Без НДС'):k==='seller_kind'?(v==='private'?'Частное лицо':'Компания'):k==='availability'?(v==='stock'?'В наличии':'Под заказ'):k==='only_photo'||k==='include_unknown'?'':k.includes('price')?money(v):k==='radius'||k==='max_mileage'?`${fmt(v)} км`:k==='max_hours'?`${fmt(v)} м/ч`:v;
 const schema=meta.fields.find(x=>k==='min_'+x.key||k==='max_'+x.key);if(schema?.unit)val=fmt(v)+' '+schema.unit;
 return {key:k,text:[labels[k],val].filter(Boolean).join(' ')};
 });
}
async function catalog(r){
 const result=await call('catalog',{filters:r.params}),f=result.filters,rows=result.ids.map(ad),section=sectionOf(f);
 if(JSON.stringify(f)!==JSON.stringify(r.params)){history.replaceState(null,'','#'+href('/catalog',f));r.params=f;}
 const allCount=state.ads.filter(a=>a.status==='active').length;
 const sectionAssets={cars:'car',commercial:'volvo',moto:'moto',water:'boat'};
 const sortItems={new:'Сначала новые',relevance:'По соответствию',price_asc:'Сначала дешевле',price_desc:'Сначала дороже',year:'Сначала свежее по году',...(f.city?{distance:'Ближе к выбранному городу'}:{}),...(section==='cars'||section==='moto'?{mileage:'Меньше пробег'}:{}),...(f.category&&meterFor(f.category)==='hours'?{hours:'Меньше моточасов'}:{})};
 const sort=options(sortItems,f.sort||'new');
 return `<form class="searchbar" data-form="search" role="search"><div class="searchfield search-with-suggest">${icon('search')}<input name="q" value="${e(f.q)}" aria-label="Поиск транспорта" placeholder="Марка, модель или тип. Например, Toyota до 4 млн" autocomplete="off" data-input="catalog-search" role="combobox" aria-autocomplete="list" aria-controls="search-suggestions" aria-expanded="false"><div id="search-suggestions" class="search-suggestions" role="listbox" hidden></div></div><button class="btn primary" type="submit">${icon('search')}<span>Найти</span></button>${button(`${icon('pin')}${e(f.city||'Вся Россия')}${icon('down')}`,'location','','location-button')}</form>
 <div class="catalog-sections" aria-label="Разделы каталога"><button class="section-tile all-section ${!section?'active':''}" data-action="section" data-section="">${icon('grid')}<strong>Весь транспорт</strong><span>${allCount} объявлений</span></button>${Object.entries(meta.sections).map(([key,label])=>`<button class="section-tile ${section===key?'active':''}" data-action="section" data-section="${key}"><img src="/assets/${sectionAssets[key]}.webp" alt=""><div><strong>${label}</strong><span>${state.ads.filter(a=>a.status==='active'&&a.section===key).length} объявлений</span></div></button>`).join('')}</div>
 ${section&&section!=='cars'?`<div class="category-chips"><button class="chip ${!f.category?'chosen':''}" data-action="category" data-category="">Все категории</button>${Object.entries(meta.category_groups[section]).map(([key,label])=>`<button class="chip ${f.category===key?'chosen':''}" data-action="category" data-category="${key}">${label}</button>`).join('')}</div>`:''}
 <div class="page-head"><div class="row"><h1>${e(meta.categories[f.category]||meta.sections[section]||'Найдите свой транспорт')}</h1><span class="muted" aria-live="polite">${rows.length} ${plural(rows.length,'объявление','объявления','объявлений')}</span></div><div class="view-tools"><select data-change="sort" aria-label="Сортировка">${sort}</select>${ib('view','grid','Плиткой','data-view="grid"',ui.view==='grid'?'selected':'')}${ib('view','list','Списком','data-view="list"',ui.view==='list'?'selected':'')}</div></div>
 <div class="mobile-filter-row mobile-only">${button('Фильтры'+(filterSummary(f).length?` <span class="count">${filterSummary(f).length}</span>`:''),'filters','filter')}<select aria-label="Сортировка" data-change="sort">${sort}</select></div>
 <div class="catalog-layout"><form class="filter-panel panel" data-form="filters"><div class="filter-fields">${filterFields(f)}</div><div class="filter-submit"><button type="submit" class="btn primary w-full">Показать ${rows.length} объявлений</button>${button('Сбросить фильтры','reset-filters','','plain w-full mt')}</div></form><section class="catalog-results">${filterSummary(f).length?`<div class="chip-row">${filterSummary(f).map(x=>`<button class="chip" data-action="remove-filter" data-key="${x.key}">${e(x.text)}${icon('close')}</button>`).join('')}</div>`:''}${rows.length?`<div class="grid ${ui.view==='list'?'list-view':''}">${rows.map(card).join('')}</div>`:empty('По этим параметрам ничего нет','Измените фильтры или сохраните поиск. Выбранные условия остаются без изменений.',button('Изменить фильтры','filters','filter','primary')+button('Сбросить','reset-filters','refresh'))}<div class="search-prompt"><div><h3>Сохраните этот поиск</h3><p>Все выбранные параметры будут под рукой</p></div>${button('Сохранить поиск','save-search','bell','soft')}</div>${button('Скопировать ссылку на поиск','share-search','clip','plain')}</section></div>`;
}
function specs(a){
 const base=[['Раздел',meta.sections[sectionOf(a)]],['Категория',meta.categories[a.category]],['Марка',a.brand],['Модель',a.model],['Год выпуска',a.year||'—']];
 const meter=meterFor(a.category);if(meter)base.push([meter==='hours'?'Наработка':'Пробег',mileage(a)]);
 for(const x of applicableFields(a)){const v=a[x.key];if(v!==null&&v!==undefined&&v!=='')base.push([x.label,x.type==='number'?fmt(v)+(x.unit?' '+x.unit:''):v]);}
 return [...base,['Состояние',a.condition==='new'?'Новое':'Б/у'],['Наличие',a.availability==='order'?'Под заказ':'В наличии'],['Город',a.city],['НДС',a.vat==='yes'?'С НДС':'Без НДС']];
}
function editorMainFields(a){
 const section=sectionOf(a),fields=applicableFields(a),meter=meterFor(a.category);
 return `<h2>Расскажите о транспорте</h2><p class="muted">Характеристики зависят от выбранной категории. Неизвестные значения можно оставить пустыми.</p><div class="field-grid single-mobile">${selectField('section','Раздел',meta.sections,section)}${selectField('category','Категория',meta.category_groups[section]||meta.categories,a.category)}</div><div class="field-grid">${field('brand','Марка',a.brand,'required maxlength="50" placeholder="Укажите марку"')}${field('model','Модель',a.model,'required maxlength="80" placeholder="Укажите модель"')}</div><div class="field-grid">${field('year','Год выпуска',a.year,'required inputmode="numeric" placeholder="2022"')}${selectField('condition','Состояние',{used:'Б/у',new:'Новое'},a.condition)}</div>${meter?field(meter,meter==='hours'?'Наработка, м/ч':'Пробег, км',a[meter],'inputmode="numeric" placeholder="Не указано"'):''}${selectField('availability','Наличие',{stock:'В наличии',order:'Под заказ'},a.availability||'stock')}<details class="editor-specs" open><summary>Характеристики категории</summary><div class="field-grid single-mobile mt">${fields.map(x=>x.type==='select'?selectField(x.key,x.label,{'':'Не указано',...x.options},a[x.key]):field(x.key,x.label+(x.unit?', '+x.unit:''),a[x.key],'inputmode="decimal" placeholder="Не указано"')).join('')}</div></details>`;
}
